// PICKER: wbase_pcfile_picker @ wbase 0x2143
int wbase_pcfile_picker() {
    char tmp_record[0x1b0];                       // [bp-0x1bc..]
    int count = 0;
    // --- PHASE 1: scan PCFILE.DBS char status array, build parallel candidate arrays ---
    for (int i = 0; i < *(int *)0x4fd2; i++) {
        if (*(byte *)(i + 0x4fd8) == 1) {
            roster_io_one_record(tmp_record, i, 0);
            strcpy(0x507a + count*8, tmp_record);                    // name (8 bytes from rec+0)
            *(int *)(count*2 + 0x50fa) = tmp_record[0x19e];          // race byte
            *(int *)(count*2 + 0x511a) = tmp_record[0x19d];          // class byte
            *(int *)(count*2 + 0x513a) = tmp_record[0x19f];          // sex byte
            *(int *)(count*2 + 0x515a) = i;                          // back-ref to char_idx
            count++;
        }
    }
    if (count == 0) return -1;
    // --- PHASE 2: build UI windows + title text ---
    int outer = ui_window_create(0, 0x13, 0x13, 5, 10, 0xfffc, 0, 0);  // x=19 y=19 w=5 h=10
    ui_window_clear(outer, 0x20, 3);
    int inner = ui_window_create(0x14, 0x13, 0x14, 5, 0x14, 0xfffb, 0, 0);  // x=19 y=20 w=5 h=20
    ui_window_clear(inner, 0x20, 3);
    char title_buf[0x10];
    load_msg_into_buf(0x4b1, title_buf);                                // top-strip title (msg 1201)
    int center_x = 10 - (strlen(title_buf) + 1)/2;
    draw_title_strip_centered(title_buf, center_x);                     // FUN_1e0e: writes into *0x3342
    ui_window_redraw_focused(*0x4fb2, 0);
    ui_window_focus(outer);
    ui_window_set_cursor(outer, 6, 1);
    draw_msg_in_window(outer, 0x4b6, 0x12);                             // outer title (msg 1206)
    ui_window_unfocus(outer);
    FUN_1e93(inner, 0);                                                  // draw 5-cell decorative bar in inner
    ui_screen_refresh();
    char cancel_text[0x18];
    load_msg_into_buf(0x4b7, cancel_text);                              // CANCEL button text (msg 1207)
    // --- PHASE 3: register mouse hotspots ---
    mouse_status_set_field(0, inner.x+2, inner.y+2, inner.x+0x12, inner.y+2);  // list top half
    mouse_status_set_field(1, inner.x+1, inner.y, inner.x+0x11, inner.y);      // list bottom half (?)
    mouse_status_set_field(2, inner.x+1, inner.y+4, inner.x+0x11, inner.y+4);  // (paging?)
    mouse_status_set_field(3, outer.x+7, outer.y+3, outer.x+7+strlen(cancel_text)+6, outer.y+3);  // CANCEL hotspot
    mouse_status_set_field(4, 0, 0, 0xff, 0);                                  // sentinel / clear
    // --- PHASE 4: input loop ---
    int cursor = 0;
    int on_cancel = 0;
    while (true) {
        if (*0x846 == 0 && on_cancel == 1) {
            ui_window_set_cursor(outer, 7, 3);
            ui_window_puts_highlight(outer, cancel_text, 0xfffb);   // df85 highlight
            FUN_1f11(inner, cursor, 0, count);                       // render rows w/ none highlighted (df85 path)
        } else {
            ui_window_set_cursor(outer, 7, 3);
            ui_window_puts(outer, cancel_text, 3);                   // dfb9 normal
            FUN_1f11(inner, cursor, 1, count);                       // render rows w/ center highlighted
        }
        int key = wbase_menu_poll_input(0x5066, 0x3598);
        if (*0x4fc4 == 1) {                                          // mouse click
            if (key == 0) key = 5;        // list center → ENTER
            else if (key == 1) key = 2;   // list-up → LEFT (page up)
            else if (key == 2) key = 4;   // list-down → RIGHT (page down)
            else if (key == 3) { on_cancel = 1; key = 5; }           // CANCEL hotspot → on_cancel + ENTER
        }
        switch (key) {
            case 1: on_cancel = 1; break;                            // UP — move to CANCEL
            case 2:                                                  // LEFT
                if (on_cancel) on_cancel = 0;
                else if (cursor > 0) cursor--;
                break;
            case 3:                                                  // DOWN
                if (on_cancel) on_cancel = 0;
                break;
            case 4:                                                  // RIGHT
                if (on_cancel) on_cancel = 0;
                else if (cursor + 1 < count) cursor++;
                break;
            case 5: goto loop_exit;                                  // ENTER
        }
    }
loop_exit:
    ui_window_destroy(outer, 0);
    ui_window_destroy(inner, 0);
    ui_window_redraw_focused(*0x3342, 0);
    ui_window_redraw_focused(*0x4fb2, 0);    // c4de — restore status bar
    return on_cancel ? -1 : cursor;
}
